#!/usr/bin/env python3
"""Extract this technique's actual C++20 fence and compare it with independent oracles.
Usage: python3 checker.py [article.mdx] [--sanitize]
"""
from pathlib import Path
import os
import shutil
import re
import subprocess
import sys
import tempfile

DEFAULT = Path(__file__).resolve().parents[1] / "src/content/docs/techniques/xor-bounded-triples-intervals.mdx"
args = [arg for arg in sys.argv[1:] if arg != "--sanitize"]
article = Path(args[0]) if args else DEFAULT
blocks = re.findall(r"^```cpp\s*\n(.*?)^```\s*$", article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError("expected exactly one complete C++ fence")
TESTS = '#include <boost/multiprecision/cpp_int.hpp>\n#include <chrono>\n#include <cstdlib>\n#include <iostream>\n#include <limits>\n#include <random>\n#include <string>\nusing I = std::int64_t;\nusing Intervals = std::vector<std::pair<I,I>>;\nusing boost::multiprecision::cpp_int;\nconstexpr I TEST_MOD = 1000000007;\nstd::uint64_t checks = 0;\nvoid require(bool condition, const std::string& message) {\n    ++checks;\n    if (!condition) { std::cerr << "FAIL: " << message << \'\\n\'; std::exit(1); }\n}\nI combination(I n, int take) {\n    if (n < take) return 0;\n    cpp_int result = 1;\n    for (int i=1;i<=take;++i) { result *= n-i+1; result /= i; }\n    return (result % TEST_MOD).convert_to<I>();\n}\nIntervals compress(const std::vector<I>& values) {\n    Intervals result;\n    for (I x : values) {\n        if (!result.empty() && result.back().second + 1 == x)\n            result.back().second = x;\n        else result.push_back({x,x});\n    }\n    return result;\n}\nstd::vector<I> direct_histogram(const std::vector<I>& values, int upper) {\n    std::vector<I> histogram(upper+1);\n    for (std::size_t i=0;i<values.size();++i)\n        for (std::size_t j=i+1;j<values.size();++j)\n            for (std::size_t k=j+1;k<values.size();++k) {\n                I need=std::max({values[i]^values[j],values[i]^values[k],values[j]^values[k]});\n                if (need<=upper) ++histogram[need];\n            }\n    for (int k=1;k<=upper;++k) histogram[k]=(histogram[k]+histogram[k-1])%TEST_MOD;\n    return histogram;\n}\nI direct(const std::vector<I>& values, I limit) {\n    I result=0;\n    for (std::size_t i=0;i<values.size();++i)\n        for (std::size_t j=i+1;j<values.size();++j)\n            for (std::size_t k=j+1;k<values.size();++k)\n                result += (values[i]^values[j])<=limit && (values[i]^values[k])<=limit\n                    && (values[j]^values[k])<=limit;\n    return result%TEST_MOD;\n}\n// Independent oracle: choose the three complete bit strings together; enforce x<y<z,\n// all three range bounds, and all three XOR bounds through prefix comparisons.\nI digit_oracle(I low, I high, I limit) {\n    constexpr int STATES=1<<11;\n    std::array<I,STATES> dp{},next{};\n    dp[0]=1;\n    for (int bit=29;bit>=0;--bit) {\n        next.fill(0);\n        int lb=(low>>bit)&1, ub=(high>>bit)&1, kb=(limit>>bit)&1;\n        for (int state=0;state<STATES;++state) if (dp[state]) {\n            for (int digits=0;digits<8;++digits) {\n                std::array<int,3> v{digits&1,(digits>>1)&1,(digits>>2)&1};\n                int ns=state;\n                bool ok=true;\n                for (int i=0;i<3;++i) {\n                    if (!(state&(1<<i)) && v[i]>ub) ok=false;\n                    if (!(state&(1<<(i+3))) && v[i]<lb) ok=false;\n                    if (v[i]<ub) ns|=1<<i;\n                    if (v[i]>lb) ns|=1<<(i+3);\n                }\n                const std::array<int,3> xors{v[0]^v[1],v[0]^v[2],v[1]^v[2]};\n                for (int i=0;i<3;++i) {\n                    if (!(state&(1<<(i+6))) && xors[i]>kb) ok=false;\n                    if (xors[i]<kb) ns|=1<<(i+6);\n                }\n                for (int i=0;i<2;++i) {\n                    if (!(state&(1<<(i+9))) && v[i]>v[i+1]) ok=false;\n                    if (v[i]<v[i+1]) ns|=1<<(i+9);\n                }\n                if (ok) next[ns]=(next[ns]+dp[state])%TEST_MOD;\n            }\n        }\n        dp=next;\n    }\n    I result=0;\n    for (int state=0;state<STATES;++state)\n        if ((state&(3<<9))==(3<<9)) result=(result+dp[state])%TEST_MOD;\n    return result;\n}\nvoid reject(const Intervals& intervals,I limit) {\n    bool threw=false;\n    try { (void)count_xor_bounded_triples(intervals,limit); }\n    catch(const std::invalid_argument&) { threw=true; }\n    require(threw,"invalid argument accepted");\n}\nint main() {\n    const auto started=std::chrono::steady_clock::now();\n    for (int mask=0;mask<(1<<12);++mask) {\n        std::vector<I> values;\n        Intervals singletons;\n        for (int x=0;x<12;++x) if (mask&(1<<x)) {values.push_back(x);singletons.push_back({x,x});}\n        const auto canonical=compress(values);\n        const auto expected=direct_histogram(values,15);\n        for (int k=1;k<=15;++k) {\n            require(count_xor_bounded_triples(canonical,k)==expected[k],"all subsets / all K");\n            require(count_xor_bounded_triples(singletons,k)==expected[k],"singleton split invariance");\n        }\n    }\n    require(count_xor_bounded_triples({{0,199}},13)==4280,"sample 1");\n    require(count_xor_bounded_triples({{1,35},{48,103},{125,127},{154,190},{195,235},{240,250}},147)==267188,"sample 2");\n    std::mt19937_64 rng(10702020);\n    for (int trial=0;trial<2200;++trial) {\n        std::vector<I> values;\n        for (I x=0;x<80;++x) if (rng()%3==0) values.push_back(x);\n        I k=1+rng()%127;\n        require(count_xor_bounded_triples(compress(values),k)==direct(values,k),"random triples");\n    }\n    for (int b=1;b<=29;++b) for (I k : {(I{1}<<b)-1,I{1}<<b}) {\n        std::vector<I> values;\n        for (I center : {I{0},I{1}<<b,I{1}<<(b-1),I{1000000000}})\n            for (int delta=-5;delta<=5;++delta) {\n                I x=center+delta;\n                if (x>=0 && x<=1000000000 && rng()%4!=0) values.push_back(x);\n            }\n        std::sort(values.begin(),values.end());\n        values.erase(std::unique(values.begin(),values.end()),values.end());\n        require(count_xor_bounded_triples(compress(values),k)==direct(values,k),"power-of-two boundary and max value");\n    }\n    // First check the independent digit oracle against the direct oracle.\n    for (I low=0;low<8;++low) for (I high=low;high<10;++high) for (I k=1;k<16;++k) {\n        std::vector<I> values;\n        for (I x=low;x<=high;++x) values.push_back(x);\n        require(digit_oracle(low,high,k)==direct(values,k),"digit oracle validation");\n    }\n    std::vector<std::array<I,3>> large_cases{\n        {0,1000000000,1000000000},{0,1000000000,1},{0,1000000000,2},\n        {0,1000000000,(I{1}<<29)-1},{0,1000000000,I{1}<<29},\n        {3,1000000000,999999999},{123456789,987654321,765432101},\n        {0,(I{1}<<29)-1,(I{1}<<29)-1},{999999990,1000000000,1000000000}\n    };\n    for (int b=1;b<=29;++b) {\n        I bound=I{1}<<b;\n        large_cases.push_back({0,std::min(I{1000000000},2*bound+7),bound-1});\n        large_cases.push_back({0,std::min(I{1000000000},2*bound+7),bound});\n    }\n    for (const auto& [low,high,k]:large_cases) {\n        I expected=digit_oracle(low,high,k);\n        require(count_xor_bounded_triples({{low,high}},k)==expected,"large interval digit oracle");\n        Intervals split;\n        for (I start=low;start<=high;) {\n            I end=std::min(high,start+std::max(I{1},(high-low)/37));\n            split.push_back({start,end}); start=end+1;\n        }\n        require(count_xor_bounded_triples(split,k)==expected,"large adjacent split invariance");\n    }\n    require(count_xor_bounded_triples({{0,(I{1}<<29)-1}},(I{1}<<29)-1)==combination(I{1}<<29,3),"count exceeds modulus");\n    Intervals sparse;\n    for (I i=0;i<19999;++i) sparse.push_back({2*i,2*i});\n    sparse.push_back({1000000000,1000000000});\n    I allowed=0;\n    for (I i=0;i<19999;++i) allowed+=((2*i)^I{1000000000})<=1000000000;\n    require(count_xor_bounded_triples(sparse,1000000000)==(combination(19999,3)+combination(allowed,2))%TEST_MOD,"max N/value independent count");\n    Intervals fragmented;\n    I total=0;\n    for(I i=0;i<20000;++i) {\n        I low=i*50000,high=low+10000+(i*7919)%25000;\n        fragmented.push_back({low,high}); total+=high-low+1;\n    }\n    const I a=count_xor_bounded_triples(fragmented,1000000000);\n    require(a>=0 && a<TEST_MOD,"max N fragmented stress");\n    // A limit containing the whole 2^29 block gives a separate closed-form stress case.\n    for(auto& interval:fragmented) {interval.first/=2;interval.second/=2;}\n    total=0;\n    for(const auto& [low,high]:fragmented) total+=high-low+1;\n    require(count_xor_bounded_triples(fragmented,(I{1}<<29)-1)==combination(total,3),"max N interval lengths");\n    require(count_xor_bounded_triples({},1)==0,"empty");\n    require(count_xor_bounded_triples({{1000000000,1000000000}},1000000000)==0,"single max value");\n    reject({},0);reject({},-1);reject({},1000000001);\n    reject({{-1,0}},1);reject({{0,1000000001}},1);reject({{4,3}},1);\n    reject({{0,3},{3,4}},1);reject({{4,5},{0,1}},1);reject({{2,2},{2,2}},1);\n    reject({{std::numeric_limits<I>::min(),0}},1);\n    reject({{0,std::numeric_limits<I>::max()}},1);\n    Intervals oversized(20001,{0,0});reject(oversized,1);\n    const double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();\n    std::cout << "Cowmistry C++20: " << checks << " checks passed; all 4096 subsets of [0,11], all K=1..15, independent triples/digit DP, boundary and maximum cases; " << seconds << "s\\n";\n}\n'
with tempfile.TemporaryDirectory(prefix="flowchartcp-cowmistry-") as directory:
    source = Path(directory) / "check.cpp"
    executable = Path(directory) / "check"
    source.write_text(blocks[0] + "\n" + TESTS)
    flags = ["-std=c++20", "-O2", "-Wall", "-Wextra", "-Werror"]
    environment = os.environ.copy()
    if "--sanitize" in sys.argv:
        flags += ["-g", "-fsanitize=address,undefined", "-fno-omit-frame-pointer"]
        # LeakSanitizer cannot run under this environment's ptrace wrapper.
        environment["ASAN_OPTIONS"] = "detect_leaks=0"
    compiler = os.environ.get("CXX") or shutil.which("g++") or shutil.which("clang++") or "c++"
    subprocess.run([compiler, *flags, str(source), "-o", str(executable)], check=True, timeout=120)
    subprocess.run([str(executable)], check=True, env=environment, timeout=120)
